<script>
  const prices = {
    USD: {
      annual: ['2.99', '4.99', '19.95', '7.99'],
      monthly: ['3.99', '6.95', '24.95', '9.99'],
      symbol: '$', flag: '🇺🇸'
    },
    CAD: {
      annual: ['3.99', '6.49', '24.95', '9.99'],
      monthly: ['4.99', '7.95', '29.95', '11.99'],
      symbol: '$', flag: '🇨🇦'
    },
    EUR: {
      annual: ['2.69', '4.79', '16.95', '7.49'],
      monthly: ['3.39', '5.95', '20.95', '8.99'],
      symbol: '€', flag: '🇪🇺'
    }
  };
  let currency = 'USD';
  let billing = 'annual';

  function updatePrices() {
    const data = prices[currency];
    document.querySelectorAll('.amount').forEach((el, i) => {
      el.textContent = data.symbol + data[billing][i];
    });
    document.querySelectorAll('.currency-code').forEach(el => el.textContent = currency);
    document.querySelectorAll('.billing-caption').forEach((el, i) => {
      if (billing === 'annual') {
        el.textContent = i === 2 ? 'Up to 10 users/month. Paid annually.' :
          i === 3 ? 'Per user, per month. Paid annually.' : 'Per month. Paid annually.';
      } else {
        el.textContent = i === 2 ? 'Up to 10 users per month.' :
          i === 3 ? 'Per user, per month.' : 'Per month.';
      }
    });
    document.getElementById('currentCurrency').textContent = currency;
    document.getElementById('currentFlag').textContent = data.flag;
    document.querySelectorAll('.currency-choice').forEach(btn => {
      btn.classList.toggle('selected', btn.dataset.currency === currency);
      btn.querySelector('.check').textContent = btn.dataset.currency === currency ? '✓' : '';
    });
  }

  document.querySelectorAll('input[name="billing"]').forEach(input => {
    input.addEventListener('change', () => {
      billing = input.value;
      updatePrices();
    });
  });

  const currencyButton = document.getElementById('currencyButton');
  const currencyMenu = document.getElementById('currencyMenu');
  currencyButton.addEventListener('click', () => {
    const open = currencyMenu.classList.toggle('open');
    currencyButton.setAttribute('aria-expanded', open);
  });
  document.querySelectorAll('.currency-choice').forEach(btn => {
    btn.addEventListener('click', () => {
      currency = btn.dataset.currency;
      updatePrices();
      currencyMenu.classList.remove('open');
      currencyButton.setAttribute('aria-expanded', 'false');
    });
  });
  document.addEventListener('click', e => {
    if (!e.target.closest('.currency-wrap')) {
      currencyMenu.classList.remove('open');
      currencyButton.setAttribute('aria-expanded', 'false');
    }
  });

  document.querySelectorAll('.plan-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      document.querySelectorAll('.plan-tab').forEach(item => {
        item.classList.remove('active');
        item.removeAttribute('aria-selected');
      });
      tab.classList.add('active');
      tab.setAttribute('aria-selected', 'true');
    });
  });
  document.querySelector('.close-announcement').addEventListener('click', () => {
    document.getElementById('announcement').style.display = 'none';
  });
  updatePrices();
</script>
